div.div:
id : Int
name : String {unique}
price : Int

code : String {id}
percentOff : Int {1..100}
minTotal : Int = 0
active : Boolean = true
expiresAt : DateTime [0..1]

id : Int
idempotencyKey : String {unique}
amount : Int
provider : PaymentProvider
status : PaymentStatus
gatewayOrderId : String {unique} {mã gửi sang cổng}
payUrl : String [0..1] {trang thanh toán của cổng}
gatewayRef : String [0..1] {mã giao dịch của cổng}
bankCode : String [0..1]
payType : String [0..1]
gatewayResult : Json [0..1] {dữ liệu gốc có chữ ký}
createdAt : DateTime
confirmedAt : DateTime [0..1] {lúc cổng xác nhận}

id : Int
name : String {unique}
unit : String {g, ml, cái}
stock : Int
version : Int = 0 {optimistic locking}
scalesWithSize : Boolean = true
